package com.asmj.marketplace.emergency;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.mapping.Document;

@Document(collection="emergency_providers")
public class EmergencyProvider {
 @Id private String id; private String ownerUserId; private String ownerEmail; private String providerName; private String providerType; private String contactPerson; private String phone; private String alternatePhone; private String email; private String description; private String categoryCode; private String categoryLabel; private String subcategoryCode; private String subcategoryLabel; private String stateCode; private String stateLabel; private String cityCode; private String cityLabel; private String pincode; private List<String> servicePincodes=new ArrayList<>(); private String operatingHours; private boolean available24x7; private String availability="AVAILABLE"; private String charges; private String imageUrl; private List<EmergencyDocument> documents=new ArrayList<>(); private String status="DRAFT"; private String adminNote; private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now(); private Instant approvedAt;
 public String getId(){return id;} public void setId(String v){id=v;} public String getOwnerUserId(){return ownerUserId;} public void setOwnerUserId(String v){ownerUserId=v;} public String getOwnerEmail(){return ownerEmail;} public void setOwnerEmail(String v){ownerEmail=v;} public String getProviderName(){return providerName;} public void setProviderName(String v){providerName=v;} public String getProviderType(){return providerType;} public void setProviderType(String v){providerType=v;} public String getContactPerson(){return contactPerson;} public void setContactPerson(String v){contactPerson=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getAlternatePhone(){return alternatePhone;} public void setAlternatePhone(String v){alternatePhone=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getCategoryCode(){return categoryCode;} public void setCategoryCode(String v){categoryCode=v;} public String getCategoryLabel(){return categoryLabel;} public void setCategoryLabel(String v){categoryLabel=v;} public String getSubcategoryCode(){return subcategoryCode;} public void setSubcategoryCode(String v){subcategoryCode=v;} public String getSubcategoryLabel(){return subcategoryLabel;} public void setSubcategoryLabel(String v){subcategoryLabel=v;} public String getStateCode(){return stateCode;} public void setStateCode(String v){stateCode=v;} public String getStateLabel(){return stateLabel;} public void setStateLabel(String v){stateLabel=v;} public String getCityCode(){return cityCode;} public void setCityCode(String v){cityCode=v;} public String getCityLabel(){return cityLabel;} public void setCityLabel(String v){cityLabel=v;} public String getPincode(){return pincode;} public void setPincode(String v){pincode=v;} public List<String> getServicePincodes(){return servicePincodes;} public void setServicePincodes(List<String> v){servicePincodes=v;} public String getOperatingHours(){return operatingHours;} public void setOperatingHours(String v){operatingHours=v;} public boolean isAvailable24x7(){return available24x7;} public void setAvailable24x7(boolean v){available24x7=v;} public String getAvailability(){return availability;} public void setAvailability(String v){availability=v;} public String getCharges(){return charges;} public void setCharges(String v){charges=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public List<EmergencyDocument> getDocuments(){return documents;} public void setDocuments(List<EmergencyDocument> v){documents=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getAdminNote(){return adminNote;} public void setAdminNote(String v){adminNote=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} public Instant getApprovedAt(){return approvedAt;} public void setApprovedAt(Instant v){approvedAt=v;}
 public static class EmergencyDocument { private String type; private String fileName; private String url; private Instant uploadedAt=Instant.now(); public EmergencyDocument(){} public EmergencyDocument(String t,String f,String u){type=t;fileName=f;url=u;} public String getType(){return type;} public void setType(String v){type=v;} public String getFileName(){return fileName;} public void setFileName(String v){fileName=v;} public String getUrl(){return url;} public void setUrl(String v){url=v;} public Instant getUploadedAt(){return uploadedAt;} public void setUploadedAt(Instant v){uploadedAt=v;} }
}
